-- V3_024: immutable dynamic A4 MC template, QR v3, 12-page service policy.
-- Apply only to an explicitly selected isolated V3 release database.

SET @a4=(SELECT paper_size_id FROM paper_sizes WHERE paper_size_code='A4');
SET @mc=(SELECT question_type_id FROM question_types WHERE question_type_code='multiple_choice');
SET @dynamic=(SELECT omr_template_id FROM omr_templates WHERE template_code='OMR-A4-DYNAMIC-CTX-V3');
